601	    const base = 0.3 + (Math.abs(vmid) % 35) / 100; // 0.30..0.64
602	    const drift = 0.03 * Math.sin(Date.now() / (6 * 3600_000) + vmid); // slow ±3%
603	    const frac = Math.min(0.95, Math.max(0.05, base + drift));
