52	  // maxmem — that's genuine live data (a customer who turned a box off really
53	  // is using 0% of it right now), so it is included exactly like a RUNNING
54	  // one rather than special-cased. The only thing dropped is an actual
55	  // failure: the vmid doesn't exist on the hypervisor (a staging/sandbox row,
56	  // or a deleted VM the DB hasn't caught up on) or the node is unreachable.
57	  // Those are silently excluded from the sums — never guessed at — the same
58	  // "an API error is our blind spot, not the customer's" rule worker/uptime.ts
59	  // already applies.
60	  const withVmid = servers.filter((s) => s.vmid != null);
61	  const liveResults = await Promise.allSettled(
62	    withVmid.map((s) =>
63	      s.node ? pveForNode(s.node).vmStatus(s.vmid as number) : vmStatus(s.vmid as number)
64	    )
65	  );
66	
67	  // Weighted by each VM's own real capacity (cores / bytes of RAM), not a
68	  // naive average of percentages — a maxed-out 1-vCPU box and an idle 8-vCPU
69	  // box are not "50% CPU" between them.
70	  let usedCoreEquiv = 0;
71	  let totalCores = 0;
72	  let usedMemBytes = 0;
73	  let totalMemBytes = 0;
74	
75	  liveResults.forEach((r, i) => {
76	    if (r.status !== "fulfilled" || !r.value) return;
77	    const s = withVmid[i];
78	    const cores = s.gamePlan?.cpuCores ?? s.plan.cpuCores;
79	    const cpuFrac = Math.max(0, Number(r.value.cpu) || 0);
80	    if (cores > 0) {
81	      usedCoreEquiv += cpuFrac * cores;
82	      totalCores += cores;
83	    }
84	    const maxmem = Math.max(0, Number(r.value.maxmem) || 0);
85	    if (maxmem > 0) {
86	      usedMemBytes += Math.min(maxmem, Math.max(0, Number(r.value.mem) || 0));
87	      totalMemBytes += maxmem;
88	    }
89	  });
90	
91	  const cpu: Metric = totalCores > 0
92	    ? { measured: true, pct: Math.min(100, (usedCoreEquiv / totalCores) * 100) }
93	    : { measured: false, pct: 0 };
94	  const memory: Metric = totalMemBytes > 0
95	    ? { measured: true, pct: Math.min(100, (usedMemBytes / totalMemBytes) * 100) }
96	    : { measured: false, pct: 0 };
97	
98	  // ---- Storage: the latest worker-collected guest-agent sample per server
99	  // (ServerDiskSample, sampled every ~10 minutes — worker/monitor.ts's
100	  // sampleServerDisks). Deliberately NOT a live get-fsinfo call here: Proxmox
101	  // RRD/status report `disk: 0` for every QEMU VM regardless of real usage
102	  // (confirmed against this box's own live cluster resources), so the only
103	  // real number comes from the guest agent, and a fresh-enough one is already
104	  // sitting in the DB without a second per-VM round trip stacked on the one
105	  // above. */
106	  const diskSamples = await Promise.all(
107	    servers.map((s) =>
108	      db.serverDiskSample.findFirst({
109	        where: { serverId: s.id },
110	        orderBy: { ts: "desc" },
111	        select: { usedBytes: true, totalBytes: true },
112	      })
113	    )
114	  );
115	  let usedDiskBytes = 0;
116	  let totalDiskBytes = 0;
117	  for (const sample of diskSamples) {
118	    if (!sample || sample.totalBytes <= 0n) continue;
119	    usedDiskBytes += Number(sample.usedBytes);
120	    totalDiskBytes += Number(sample.totalBytes);
121	  }
122	  const storage: Metric = totalDiskBytes > 0
123	    ? { measured: true, pct: Math.min(100, (usedDiskBytes / totalDiskBytes) * 100) }
124	    : { measured: false, pct: 0 };
125	
126	  // ---- Network: the exact same metered counters and 30-day rolling window
127	  // the Billing page's Bandwidth card reads (lib/bandwidth.ts) — one source
128	  // of truth for "how much has this server actually moved", not a second,
129	  // possibly-drifting formula invented here. ----
130	  const bwHealth = await readBwMeterHealth();
131	  let usedBwBytes = 0;
132	  let allowanceBwBytes = 0;
133	  let bwMeasuredAny = false;
134	  let bwPartialAny = false;
135	  let earliestMeasuredFrom: Date | null = null;
136	  for (const s of servers) {
137	    const view = bwUsageView(s, s.plan.bandwidthTB * 1e12, bwHealth);
138	    if (!view.measured) continue;
139	    bwMeasuredAny = true;
140	    usedBwBytes += view.usedBytes;
141	    if (view.allowanceBytes > 0) allowanceBwBytes += view.allowanceBytes;
142	    if (view.partial) bwPartialAny = true;
143	    if (view.measuredFrom && (!earliestMeasuredFrom || view.measuredFrom < earliestMeasuredFrom)) {
144	      earliestMeasuredFrom = view.measuredFrom;
145	    }
146	  }
147	  const network = {
148	    measured: bwMeasuredAny,
149	    pct: bwMeasuredAny && allowanceBwBytes > 0 ? Math.min(100, (usedBwBytes / allowanceBwBytes) * 100) : 0,
150	    usedBytes: usedBwBytes,
151	    partial: bwPartialAny,
152	    sinceIso: earliestMeasuredFrom ? earliestMeasuredFrom.toISOString() : null,
153	  };
154	
155	  return NextResponse.json({ cpu, memory, storage, network }, { headers: NO_STORE_HEADERS });
156	}
