/// cache activity shows falsely high "memory used" (cache Linux would
/// instantly reclaim counts as "used") even though the guest is nowhere
/// near actually out of RAM. `usedBytes` here is `MemTotal - MemAvailable`
/// (kB from /proc/meminfo, converted to bytes) — the genuine, cache-excluded
/// figure — so it mirrors ServerDiskSample's used/total convention exactly
/// rather than inventing a third "available" column. Pruned on the same
/// rolling retention window by the sampler.
model ServerMemSample {
  id         String   @id @default(cuid())
  serverId   String
  ts         DateTime @default(now())
  usedBytes  BigInt
  totalBytes BigInt

  @@index([serverId, ts])
}

