594	  client: GuestAgentClient,
595	  node: string,
596	  vmid: number,
597	  sandboxTotalBytes?: number
598	): Promise<GuestDiskUsage | null> {
599	  if (SANDBOX) {
600	    const total = sandboxTotalBytes && sandboxTotalBytes > 0 ? sandboxTotalBytes : 40 * 1024 ** 3;
601	    const base = 0.3 + (Math.abs(vmid) % 35) / 100; // 0.30..0.64
602	    const drift = 0.03 * Math.sin(Date.now() / (6 * 3600_000) + vmid); // slow ±3%
603	    const frac = Math.min(0.95, Math.max(0.05, base + drift));
604	    return { usedBytes: Math.round(total * frac), totalBytes: total };
605	  }
606	
607	  try {
608	    const res = await client.get(`/nodes/${node}/qemu/${vmid}/agent/get-fsinfo`);
609	    // The agent wraps the array in { result: [...] }; tolerate a bare array too.
610	    const list: any[] = Array.isArray(res?.result)
611	      ? res.result
612	      : Array.isArray(res)
613	        ? res
614	        : [];
615	    if (list.length === 0) return null;
616	
617	    const real = list.filter((fs) => {
618	      const type = String(fs?.type ?? "").toLowerCase();
619	      const mp = String(fs?.mountpoint ?? "");
620	      if (PSEUDO_FS_TYPES.has(type)) return false;
621	      if (isIgnorableMount(mp)) return false;
622	      const total = Number(fs?.["total-bytes"]);
623	      return Number.isFinite(total) && total > 0;
624	    });
625	    if (real.length === 0) return null;
626	
627	    // Prefer the real root filesystem; otherwise the largest real mount.
628	    const root =
629	      real.find((fs) => String(fs?.mountpoint) === "/") ??
630	      real.sort((a, b) => Number(b?.["total-bytes"]) - Number(a?.["total-bytes"]))[0];
631	
632	    const usedBytes = Number(root?.["used-bytes"]);
