// ---------------------------------------------------------------------------
// In-guest memory usage via the QEMU guest agent (/proc/meminfo)
// ---------------------------------------------------------------------------

/**
 * Real memory picture as reported from *inside* the guest: total RAM and the
 * kernel's own MemAvailable estimate (spare + genuinely-reclaimable
 * disk/page cache) — NOT Proxmox's raw balloon `mem`/`maxmem`, which is
 * MemFree-based and counts reclaimable page cache as "used". See
 * ServerMemSample's schema comment for why that distinction matters.
 */
export type GuestMemUsage = { totalBytes: number; availBytes: number };

/** Any client exposing `get` + `post` (satisfied by `pve` and `pveFor(...)`) —
 *  reading a file through the guest agent needs open/read/close, unlike
 *  get-fsinfo's single GET. */
export type GuestAgentRwClient = GuestAgentClient & {
  post: (path: string, params?: Record<string, any>) => Promise<any>;
};

/** Pull a base64 payload + eof flag out of a guest-agent file-read reply,
 *  tolerating the handful of field-name spellings PVE has used across
 *  versions for the same qga `guest-file-read` fields. */
function unwrapFileRead(res: any): { b64: string; eof: boolean; count: number } {
  const r = res?.result ?? res ?? {};
  const b64 = String(r["content"] ?? r["buf-b64"] ?? r["out-data"] ?? r["data"] ?? "");
  const eof = Boolean(r["eof"]);
  const count = Number(r["bytes-read"] ?? r["count"] ?? 0) || 0;
  return { b64, eof, count };
}

/**
 * Read a small text file out of the guest via the QEMU guest agent's
 * file-open/file-read/file-close trio (there is no dedicated "get meminfo"
 * qga command the way there is `get-fsinfo` for disk). Caps total bytes read
 * so a surprising target file can't loop forever. Best-effort: returns null
 * on any failure, and always closes the handle it opened.
 */
async function readGuestFile(
  client: GuestAgentRwClient,
  node: string,
  vmid: number,
  path: string,
  maxBytes = 262_144
): Promise<string | null> {
  let handle: number | undefined;
  try {
    const opened = await client.post(`/nodes/${node}/qemu/${vmid}/agent/file-open`, {
      file: path,
      mode: "r",
    });
    handle = Number(opened?.fd ?? opened?.result?.fd ?? opened);
    if (!Number.isFinite(handle)) return null;

    let out = "";
    for (let i = 0; i < 8 && out.length < maxBytes; i++) {
      const res = await client.get(`/nodes/${node}/qemu/${vmid}/agent/file-read`, {
        handle,
        count: 65536,
      });
