// Keep in-guest memory samples for the same ~5 weeks as disk samples, for the
// same reason: bounded table, always enough history for a 30-day chart.
const MEM_SAMPLE_RETENTION_DAYS = 35;

/**
 * Sample real in-guest memory for every RUNNING VM via the QEMU guest agent
 * and persist a point into ServerMemSample. Runs on the monitor cadence,
 * alongside sampleServerDisks — same reasoning applies here: Proxmox's own
 * `mem`/`maxmem` balloon fields are MemFree-based, not MemAvailable-based, so
 * a VM with ordinary disk/page-cache activity can show falsely high "memory
 * used" even though the guest has plenty of genuinely spare RAM. Asking the
 * guest's own /proc/meminfo for MemAvailable is the only honest source,
 * exactly like get-fsinfo is the only honest source for disk usage.
 *
 * Best-effort throughout: a missing/not-ready guest agent yields null and is
 * simply skipped — it never errors the sweep. In SANDBOX getGuestMemUsage
 * returns a synthetic value, so staging still builds a realistic history.
 * Also prunes samples older than the retention window each pass.
 */
export async function sampleServerMemory(): Promise<void> {
  // Retention prune first (cheap, and keeps the table bounded even if sampling
  // below throws for every server).
  try {
    const cutoff = new Date(Date.now() - MEM_SAMPLE_RETENTION_DAYS * 24 * 60 * 60_000);
    await db.serverMemSample.deleteMany({ where: { ts: { lt: cutoff } } });
  } catch (e) {
    console.error("[monitor] mem-sample prune error", e);
  }

  let servers: Array<{
    id: string;
    vmid: number | null;
    node: any;
    plan: { ramMB: number };
    gamePlan: { ramMB: number } | null;
  }>;
  try {
    servers = await db.server.findMany({
      where: { status: "RUNNING", vmid: { not: null } },
      select: {
        id: true,
        vmid: true,
        plan: { select: { ramMB: true } },
        gamePlan: { select: { ramMB: true } },
        node: {
          select: { pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true },
        },
      },
    });
  } catch (e) {
    console.error("[monitor] mem-sample: list servers error", e);
    return;
  }

  for (const s of servers) {
    if (s.vmid == null) continue;
    try {
      const client = s.node
        ? pveFor({
            apiUrl: s.node.apiUrl,
            pveNode: s.node.pveNode,
            tokenId: s.node.tokenId,
            tokenSecret: s.node.tokenSecret,
          })
        : pve;
      const pnode = s.node?.pveNode ?? defaultNode;
      // Only used to size the synthetic SANDBOX value — the real path reads
      // MemTotal straight from the guest, so it needs no plan lookup at all.
      const ramMB = s.gamePlan?.ramMB ?? s.plan.ramMB;
      const usage = await getGuestMemUsage(client, pnode, s.vmid, ramMB * 1024 * 1024);
      if (!usage) continue; // agent not ready — skip, no error
      const usedBytes = Math.max(0, usage.totalBytes - usage.availBytes);
      await db.serverMemSample.create({
        data: {
          serverId: s.id,
          usedBytes: BigInt(Math.max(0, Math.round(usedBytes))),
          totalBytes: BigInt(Math.max(0, Math.round(usage.totalBytes))),
        },
      });
    } catch (e) {
      console.error(`[monitor] mem-sample error for server ${s.id}`, e);
    }
  }
}

