// RAM specifically comes from the worker-collected guest-agent sample
// (ServerMemSample), not the live `mem`/`maxmem` above — those balloon-stat
// fields are MemFree-based, not MemAvailable-based, so a VM with ordinary
// disk/page-cache activity reads falsely high "memory used" even with
// plenty of genuinely spare RAM (confirmed against a real running server:
// balloon said ~90% used, the guest's own free -h said ~25%). CPU stays
// live above since that reading has no such distortion.
const memSampleByServerId = new Map(
  await Promise.all(
    servers.map(async (s) => {
      const sample = await db.serverMemSample.findFirst({
        where: { serverId: s.id },
        orderBy: { ts: "desc" },
        select: { usedBytes: true, totalBytes: true },
      });
      return [s.id, sample] as const;
    }),
  ),
);

