60	  const nodes = await db.node.findMany({ where: { enabled: true }, orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }] });
61	
62	  // vmids can collide across physical nodes, so the VM table is built per-node
63	  // and each row is tagged with its own node — one node's Proxmox API being
64	  // down doesn't blank the others, it just omits that node's rows.
65	  let vms: any[] = [];
66	  let pveOk = true;
67	  if (nodes.length === 0) {
68	    try {
69	      vms = (await listVms()).filter((v) => !v.template).map((v) => ({ ...v, __nodeId: null, __nodeName: null }));
70	    } catch {
71	      pveOk = false;
72	    }
73	  } else {
74	    const perNode = await Promise.all(
75	      nodes.map(async (n) => {
76	        try {
77	          const list = await listVms(pveForNode(n));
78	          return { ok: true, rows: list.filter((v: any) => !v.template).map((v: any) => ({ ...v, __nodeId: n.id, __nodeName: n.name })) };
79	        } catch {
80	          return { ok: false, rows: [] as any[] };
81	        }
82	      })
83	    );
84	    vms = perNode.flatMap((r) => r.rows);
85	    pveOk = perNode.some((r) => r.ok);
86	  }
87	  vms.sort((a, b) => a.vmid - b.vmid);
88	
89	  const [servers, storage, ram, wh, stuck, backups, uptime, jobs24h, incidents] = await Promise.all([
90	    db.server.findMany({
91	      where: { vmid: { not: null } },
92	      select: { id: true, vmid: true, hostname: true, nodeId: true, user: { select: { email: true } } },
93	    }),
