102	  ]);
103	  // Keyed by (node, vmid) — a bare vmid key would collide once two nodes both
104	  // have e.g. vmid 105, silently showing one customer's row for another's VM.
105	  const byVmid = new Map(servers.map((s) => [`${s.nodeId ?? "primary"}:${s.vmid}`, s]));
106	
107	  // Incident manager shows open first, then recently-resolved. IncidentView is
108	  // already the serialisable, public-safe shape AdminIncident expects.
109	  const allIncidents: AdminIncident[] = [...incidents.open, ...incidents.resolved];
110	  const failurePct = jobs24h.failureRate === null ? null : jobs24h.failureRate * 100;
111	
112	  // Per-node — never merged, so one node's stale/broken backups can't hide
113	  // behind another's healthy ones. A node is "an issue" if its storage wasn't
114	  // listable at all, or if it's listable but shows zero backups ever, or if its
115	  // newest backup is older than the staleness window.
116	  const backupIssues = backups.filter(
117	    (b) => !b.reachable || b.newestCtime === null || Date.now() - b.newestCtime * 1000 > BACKUP_STALE_MS
118	  );
119	
