if (servers.length === 0) {
  return "You don't have any servers on your Nxeon account yet.";
}

// Memory comes from the worker-collected guest-agent sample (ServerMemSample),
// not the live vmStatus() call below — Proxmox's own `mem`/`maxmem` balloon
// fields are MemFree-based, not MemAvailable-based, so a server with ordinary
// disk/page-cache activity would report falsely high "memory used" here even
// with plenty of genuinely spare RAM. Same source the dashboard now reads.
const memSamples = await Promise.all(
  (servers as any[]).map((s) =>
    db.serverMemSample.findFirst({
      where: { serverId: s.id },
      orderBy: { ts: "desc" },
      select: { usedBytes: true, totalBytes: true },
    })
  )
);
const memByServerId = new Map((servers as any[]).map((s, i) => [s.id, memSamples[i]]));

const lines: string[] = [`**Your Nxeon servers**`];
for (const s of servers as any[]) {
  const kind = s.gamePlanId ? "🎮" : "🖥️";
  const label = `${kind} **${s.hostname}** — ${s.status}`;
  if (s.status !== "RUNNING" || !s.vmid) {
    lines.push(label);
    continue;
  }
  try {
    // Through the server's OWN node — vmids collide across nodes, so a
    // Hetzner-hosted customer's /status would otherwise silently show the
    // primary node's stats for that vmid instead of their real server's.
    const stat = s.node ? await pveForNode(s.node).vmStatus(s.vmid) : await vmStatus(s.vmid);
    const cpu = typeof stat?.cpu === "number" ? `${Math.round(stat.cpu * 100)}%` : "—";
    const sample = memByServerId.get(s.id);
    const mem = sample && sample.totalBytes > 0n
      ? `${fmtBytes(Number(sample.usedBytes))} / ${fmtBytes(Number(sample.totalBytes))}`
      : "not measured yet";
    const uptime = typeof stat?.uptime === "number" ? fmtUptime(stat.uptime) : "—";
    lines.push(`${label}\n     CPU ${cpu} · RAM ${mem} · up ${uptime}`);
  } catch {
    lines.push(`${label}\n     (live stats unavailable right now)`);
  }
}
return lines.join("\n");

