import { db } from "/opt/nxeon-wt-mem-fix/lib/db.ts";
import { pveFor, getGuestMemUsage } from "/opt/nxeon-wt-mem-fix/lib/proxmox.ts";

const s = await db.server.findFirst({
  where: { hostname: { contains: "throarbin" } },
  select: {
    id: true, hostname: true, vmid: true, status: true,
    plan: { select: { ramMB: true } },
    gamePlan: { select: { ramMB: true } },
    node: { select: { pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true } },
  },
});

if (!s) { console.error("server not found"); process.exit(1); }

const client = pveFor({
  apiUrl: s.node.apiUrl,
  pveNode: s.node.pveNode,
  tokenId: s.node.tokenId,
  tokenSecret: s.node.tokenSecret,
});

const ramMB = s.gamePlan?.ramMB ?? s.plan.ramMB;
console.log("Querying guest-agent /proc/meminfo for", s.hostname, "vmid", s.vmid, "on", s.node.pveNode);
const usage = await getGuestMemUsage(client, s.node.pveNode, s.vmid, ramMB * 1024 * 1024);
console.log("getGuestMemUsage() ->", usage);

if (!usage) {
  console.error("guest agent did not answer / no data");
  process.exit(1);
}

const usedBytes = Math.max(0, usage.totalBytes - usage.availBytes);
const row = await db.serverMemSample.create({
  data: {
    serverId: s.id,
    usedBytes: BigInt(Math.max(0, Math.round(usedBytes))),
    totalBytes: BigInt(Math.max(0, Math.round(usage.totalBytes))),
  },
});
console.log("Inserted ServerMemSample row:", JSON.stringify(row, (k, v) => typeof v === "bigint" ? v.toString() : v, 2));

const GB = 1024 ** 3;
console.log(`\nSanity check: total=${(usage.totalBytes / GB).toFixed(2)}GB, available=${(usage.availBytes / GB).toFixed(2)}GB, genuinely-used=${(usedBytes / GB).toFixed(2)}GB (${((usedBytes / usage.totalBytes) * 100).toFixed(1)}%)`);
process.exit(0);

