import { db } from "/opt/nxeon-wt-mem-fix/lib/db.ts";
import { withServerSsh, exec } from "/opt/nxeon-wt-mem-fix/lib/ssh-exec.ts";

// Exercises the EXACT same parsing regexes getGuestMemUsage() uses
// (lib/proxmox.ts), against real /proc/meminfo text, to prove the parsing
// logic itself is correct — independent of the guest-agent transport issue
// (see report: Proxmox API token lacks VM.GuestAgent.FileRead/Unrestricted).
function parseMeminfo(text) {
  const totalMatch = /^MemTotal:\s+(\d+)\s*kB/m.exec(text);
  const availMatch = /^MemAvailable:\s+(\d+)\s*kB/m.exec(text);
  if (!totalMatch || !availMatch) return null;
  const totalBytes = Number(totalMatch[1]) * 1024;
  const availBytes = Number(availMatch[1]) * 1024;
  return { totalBytes, availBytes: Math.max(0, Math.min(availBytes, totalBytes)) };
}

const s = await db.server.findFirst({
  where: { hostname: { contains: "throarbin" } },
  select: {
    id: true, hostname: true, vmid: true, sshPort: true, ipAddress: true,
    rootPassword: true, rootPasswordEnc: true, sshManagementKeyEnc: true,
    node: { select: { publicIp: true } },
    dedicatedIp: { select: { address: true } },
  },
});

const out = await withServerSsh(s, async (conn) => {
  const meminfo = await exec(conn, "cat /proc/meminfo", 12000);
  const freeh = await exec(conn, "free -b", 12000);
  return { meminfo: meminfo.stdout, freeh: freeh.stdout };
});

const usage = parseMeminfo(out.meminfo);
if (!usage) { console.error("parse failed"); process.exit(1); }
const usedBytes = Math.max(0, usage.totalBytes - usage.availBytes);

