console.log("  usedBytes (total-avail):", usedBytes, `(${(usedBytes / 1024 ** 3).toFixed(2)} GiB, ${((usedBytes / usage.totalBytes) * 100).toFixed(1)}%)`);
console.log("\nfree -b (raw, for cross-check):\n", out.freeh);

const row = await db.serverMemSample.create({
  data: {
    serverId: s.id,
    usedBytes: BigInt(Math.round(usedBytes)),
    totalBytes: BigInt(Math.round(usage.totalBytes)),
  },
});
console.log("\nInserted ServerMemSample row:", JSON.stringify(row, (k, v) => typeof v === "bigint" ? v.toString() : v, 2));
