/** Any client exposing `get` (satisfied by `pve` and `pveFor(...)`) — a plain
 *  alias of GuestAgentClient kept distinct in case a future PVE version needs
 *  a POST here (older docs describe an open/read/close trio; the live cluster
 *  this was built against only exposes the single GET below — see the doc
 *  comment on readGuestFile). */
export type GuestAgentRwClient = GuestAgentClient;

/** Pull a base64 payload out of a guest-agent file-read reply, tolerating the
 *  couple of field-name spellings PVE has used across versions for the same
 *  qga `guest-file-read` content field. */
function unwrapFileRead(res: any): { b64: string } {
  const r = res?.result ?? res ?? {};
  const b64 = String(r["content"] ?? r["buf-b64"] ?? r["out-data"] ?? r["data"] ?? "");
  return { b64 };
}

/**
 * Read a small text file out of the guest via the QEMU guest agent.
 *
 * NOTE: some PVE docs describe a `guest-file-open` / `file-read` / `file-close`
 * trio (mirroring the raw qga protocol). The actual REST API on the live
 * cluster this was built against does NOT expose `file-open`/`file-close` as
 * endpoints at all (confirmed live: both 501 "not implemented") — it exposes
 * exactly one call, `GET .../agent/file-read?file=<path>`, which opens, reads
 * the whole file, and closes it server-side in one round trip. That single
 * call is what this function makes.
 *
 * Best-effort like getGuestDiskUsage: returns null on any error, including a
 * guest agent that isn't ready. ALSO returns null — same as "not ready" — when
 * the API token lacks the needed guest-agent ACL: confirmed live against a
 * real server, `get-fsinfo` (used for disk, above) only needs
 * `VM.GuestAgent.Audit`, but `file-read` needs `VM.GuestAgent.FileRead` or
 * `VM.GuestAgent.Unrestricted`, which the platform's Proxmox API token does
 * NOT currently have (403 "Permission check failed"). Until an operator grants
 * that permission to the token's PVE role, this will degrade to "no sample" on
 * every real server — never a crash, never a fabricated number, exactly the
 * same honest degrade as a genuinely unready agent.
 */
async function readGuestFile(
  client: GuestAgentRwClient,
  node: string,
  vmid: number,
  path: string
): Promise<string | null> {
  try {
    const res = await client.get(`/nodes/${node}/qemu/${vmid}/agent/file-read`, { file: path });
    const { b64 } = unwrapFileRead(res);
    if (!b64) return null;
    return Buffer.from(b64, "base64").toString("utf8");
  } catch {
    // Agent not ready, VM stopped, or (currently, on this token) a
    // VM.GuestAgent.FileRead/Unrestricted permission gap — all the same
    // "we don't have this sample" outcome to the caller.
    return null;
  }
}

